request.reusedSocket

Added in: v13.0.0, v12.16.0

• Type: <boolean> Whether the request is sent through a reused socket.

When sending a request through a keep-alive-enabled agent, the underlying socket might be reused. If the server closes the connection at the same time that the agent reuses it, the request may encounter an ECONNRESET error.

The following example sends requests near the server's keep-alive timeout to make this race easier to reproduce. It sets server.keepAliveTimeoutBuffer to 0 so the internal socket timeout matches server.keepAliveTimeout.

    import http from 'node:http';
    const agent = new http.Agent({ keepAlive: true });
    const server = http.createServer(
      { keepAliveTimeout: 3000, keepAliveTimeoutBuffer: 0 },
      (req, res) => {
        res.write('hello\n');
        res.end();
      },
    );
    server.listen(3000);

    setInterval(() => {
      http.get('http://localhost:3000', { agent }, (res) => {
        res.resume();
      });
    }, 3000);
    const http = require('node:http');
    const agent = new http.Agent({ keepAlive: true });
    const server = http.createServer(
      { keepAliveTimeout: 3000, keepAliveTimeoutBuffer: 0 },
      (req, res) => {
        res.write('hello\n');
        res.end();
      },
    );
    server.listen(3000);

    setInterval(() => {
      http.get('http://localhost:3000', { agent }, (res) => {
        res.resume();
      });
    }, 3000);

    javascript

By checking request.reusedSocket, an application can retry idempotent requests that fail because a reused connection was reset.

    import http from 'node:http';
    const agent = new http.Agent({ keepAlive: true });

    function retriableRequest() {
      const req = http
        .get('http://localhost:3000', { agent }, (res) => {
          // ...
        })
        .on('error', (err) => {
          // Check if retry is needed
          if (req.reusedSocket && err.code === 'ECONNRESET') {
            retriableRequest();
          }
        });
    }

    retriableRequest();
    const http = require('node:http');
    const agent = new http.Agent({ keepAlive: true });

    function retriableRequest() {
      const req = http
        .get('http://localhost:3000', { agent }, (res) => {
          // ...
        })
        .on('error', (err) => {
          // Check if retry is needed
          if (req.reusedSocket && err.code === 'ECONNRESET') {
            retriableRequest();
          }
        });
    }

    retriableRequest();

