    // spin the CPU for 500 milliseconds
    const now = Date.now();
    while (Date.now() - now < 500);

    console.log(cpuUsage(startUsage));
    // { user: 514883, system: 11226 }
    const { cpuUsage } = require('node:process');

    const startUsage = cpuUsage();
    // { user: 38579, system: 6986 }

    // spin the CPU for 500 milliseconds
    const now = Date.now();
    while (Date.now() - now < 500);

    console.log(cpuUsage(startUsage));
    // { user: 514883, system: 11226 }

